DIFFERENCE_KINDS <- c("none", "first", "seasonal", "both")
difference <- function(values, season, kind) {
    n <- length(values)
    if (kind == "none") return(list(values = values, offset = 0L))
    if (kind == "first") return(list(values = values[-1L] - values[-n], offset = 1L))
    if (kind == "seasonal") return(list(
        values = values[seq.int(season + 1L, n)] - values[seq_len(n - season)],
        offset = season
    ))
    times <- seq.int(season + 2L, n)
    list(
        values = (values[times] - values[times - 1L]) - (values[times - season] - values[times - season - 1L]),
        offset = season + 1L
    )
}
autocorrelation <- function(values, max_lag) {
    average <- series_mean(values)
    centered <- values - average
    n <- length(values)
    variance <- ordered_sum(centered * centered) / n
    correlations <- 1
    for (lag in seq_len(max_lag)) {
        times <- seq_len(n - lag)
        numerator <- ordered_sum(centered[times] * centered[times + lag])
        correlations <- c(correlations, numerator / n / variance)
    }
    list(mean = average, variance = variance, correlations = correlations)
}
durbin_levinson <- function(correlations) {
    coefficients <- list(numeric())
    partial <- 0
    variances <- 1
    for (order in seq_len(length(correlations) - 1L)) {
        previous <- tail(coefficients, 1L)[[1L]]
        indices <- seq_len(order - 1L)
        correction <- ordered_sum(previous[indices] * correlations[order - indices + 1L])
        theta <- (correlations[order + 1L] - correction) / tail(variances, 1L)
        current <- c(previous[indices] - theta * previous[order - indices], theta)
        coefficients <- c(coefficients, list(current))
        partial <- c(partial, theta)
        variances <- c(variances, tail(variances, 1L) * (1 - theta * theta))
    }
    list(coefficients = coefficients, partial = partial, variances = variances)
}
ar_residuals <- function(values, average, coefficients) {
    order <- length(coefficients)
    vapply(
        seq.int(order + 1L, length(values)),
        function(i) values[i] - average - ordered_sum(coefficients * (values[i - seq_len(order)] - average)),
        0
    )
}
ar_forecast <- function(values, differenced, offset, kind, average, coefficients, origin, steps, season) {
    transformed <- differenced[seq_len(origin - offset)]
    extended <- values[seq_len(origin)]
    result <- numeric(steps)
    for (step in seq_len(steps)) {
        predicted <- average + ordered_sum(coefficients * (transformed[length(transformed) - seq_along(coefficients) + 1L] - average))
        transformed <- c(transformed, predicted)
        n <- length(extended)
        if (kind == "first") predicted <- predicted + extended[n] else if (kind == "seasonal") predicted <- predicted + extended[n - season + 1L] else if (kind == "both") predicted <- predicted + extended[n] + extended[n - season + 1L] - extended[n - season]
        extended <- c(extended, predicted)
        result[step] <- predicted
    }
    result
}
ljung_box <- function(errors, lags) {
    n <- length(errors)
    correlations <- autocorrelation(errors, max(lags))$correlations
    lapply(lags, function(lag) {
        indices <- seq_len(lag)
        q <- n * (n + 2L) * ordered_sum(correlations[indices + 1L] * correlations[indices + 1L] / (n - indices))
        x <- q / 2
        term <- 1
        terms <- term
        for (i in seq_len(lag %/% 2L - 1L)) {
            term <- term * x / i
            terms <- c(terms, term)
        }
        list(lag = lag, q = q, p = exp(-x) * ordered_sum(terms))
    })
}

seasonal_scale <- function(values, season) {
    times <- seq.int(season + 1L, length(values))
    ordered_sum(abs(values[times] - values[times - season])) / (length(values) - season)
}
accuracy <- function(actual, predicted, scale) {
    n <- length(actual)
    errors <- actual - predicted
    mae <- ordered_sum(abs(errors)) / n
    list(me = ordered_sum(errors) / n, mae = mae, rmse = sqrt(ordered_sum(errors * errors) / n), mape = 100 * ordered_sum(abs(errors) / actual) / n,
         smape = 100 * ordered_sum(2 * abs(errors) / (abs(actual) + abs(predicted))) / n, mase = mae / scale)
}
winkler <- function(actual, low, high, multiplier) {
    if (actual < low) return(high - low + multiplier * (low - actual))
    if (actual > high) return(high - low + multiplier * (actual - high))
    high - low
}
rank_models <- function(names, metrics) names[order(
    vapply(names, function(name) metrics[[name]]$rmse, 0),
    seq_along(names)
)]

csv_rows <- function(name) strsplit(readLines(file.path("input", name))[-1L], ",", fixed = TRUE)
read_inputs <- function() {
    series <- list()
    for (row in csv_rows("series.csv")) {
        name <- row[1L]
        if (is.null(series[[name]])) series[[name]] <- list(
            name = name,
            periods = character(),
            raw = integer(),
            events = list(),
            policy = NULL
        )
        series[[name]]$periods <- c(series[[name]]$periods, row[2L])
        series[[name]]$raw <- c(series[[name]]$raw, if (row[3L] == "NA") NA_integer_ else as.integer(row[3L]))
    }
    for (row in csv_rows("events.csv")) series[[row[1L]]]$events[[row[2L]]] <- row[3L]
    for (row in csv_rows("inventory.csv")) series[[row[1L]]]$policy <- list(
        on_hand = as.integer(row[2L]),
        lead_time = as.integer(row[3L]),
        review = as.integer(row[4L]),
        service = as.numeric(row[5L])
    )
    settings <- list()
    for (fields in strsplit(readLines("input/params.txt"), " ", fixed = TRUE)) {
        key <- fields[1L]
        values <- fields[-1L]
        settings[[key]] <- if (key %in% c(
            "alpha",
            "beta",
            "gamma",
            "phi",
            "interval"
        )) as.numeric(values) else if (key == "ljung_box") as.integer(values) else if (key == "outlier") as.numeric(values[1L]) else as.integer(values[1L])
    }
    list(records = unname(series), settings = settings)
}
next_month <- function(period) {
    parts <- as.integer(strsplit(period, "-", fixed = TRUE)[[1L]])
    year <- parts[1L] + parts[2L] %/% 12L
    month <- parts[2L] %% 12L + 1L
    sprintf("%04d-%02d", year, month)
}
real_format <- function(value) {
    if (is.na(value)) return("NA")
    text <- sprintf("%.4f", value)
    if (text == "-0.0000") "0.0000" else text
}
write_lines <- function(name, lines) {
    dir.create("output", showWarnings = FALSE)
    writeLines(lines, file.path("output", name), useBytes = TRUE)
}

smoothing_recurse <- function(name, values, season, parameters) {
    alpha <- parameters$alpha
    beta <- if (is.null(parameters$beta)) 0 else parameters$beta
    phi <- if (is.null(parameters$phi)) 1 else parameters$phi
    gamma <- if (is.null(parameters$gamma)) 0 else parameters$gamma
    seasonal <- name %in% c("hw_add", "hw_mult")
    if (seasonal) {
        level <- ordered_sum(values[seq_len(season)]) / season
        slope <- (ordered_sum(values[seq.int(season + 1L, 2L * season)]) / season - level) / season
        components <- if (name == "hw_add") values[seq_len(season)] - level else values[seq_len(season)] / level
    } else {
        level <- values[1L]
        slope <- if (name == "ses") 0 else (values[season + 1L] - values[1L]) / season
        components <- NULL
    }
    states <- list()
    errors <- numeric(length(values))
    for (t in seq_along(values)) {
        observed <- values[t]
        states[[t]] <- list(level = level, slope = slope, components = components)
        if (name == "ses") {
            predicted <- level
            next_level <- alpha * observed + (1 - alpha) * level
            next_slope <- slope
        } else if (seasonal) {
            position <- (t - 1L) %% season + 1L
            previous <- components[position]
            base <- level + slope
            if (name == "hw_add") {
                predicted <- base + previous
                next_level <- alpha * (observed - previous) + (1 - alpha) * base
                components[position] <- gamma * (observed - base) + (1 - gamma) * previous
            } else {
                predicted <- base * previous
                next_level <- alpha * (observed / previous) + (1 - alpha) * base
                components[position] <- gamma * (observed / base) + (1 - gamma) * previous
            }
            next_slope <- beta * (next_level - level) + (1 - beta) * slope
        } else {
            predicted <- level + phi * slope
            next_level <- alpha * observed + (1 - alpha) * predicted
            next_slope <- beta * (next_level - level) + (1 - beta) * phi * slope
        }
        errors[t] <- observed - predicted
        level <- next_level
        slope <- next_slope
    }
    states[[length(values) + 1L]] <- list(level = level, slope = slope, components = components)
    list(errors = errors, states = states)
}
smoothing_forecast <- function(name, state, parameters, origin, steps, season) {
    level <- state$level
    slope <- state$slope
    components <- state$components
    if (name == "ses") return(rep(level, steps))
    result <- numeric(steps)
    if (name %in% c("holt", "damped")) {
        phi <- if (is.null(parameters$phi)) 1 else parameters$phi
        power <- phi
        accumulated <- 0
        for (step in seq_len(steps)) {
            accumulated <- accumulated + power
            result[step] <- level + accumulated * slope
            power <- power * phi
        }
    } else for (step in seq_len(steps)) {
        component <- components[(origin + step - 1L) %% season + 1L]
        base <- level + step * slope
        result[step] <- if (name == "hw_add") base + component else base * component
    }
    result
}
